#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("NO_INPUT\n");
        return 0;
    }
    int n = strtol(argv[1], NULL, 10);
    int k = strtol(argv[2], NULL, 10);
    if (n <= 0 || k <= 0) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (k > n) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    int *circle = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        circle[i] = i + 1;
    }
    int index = 0;
    while (n > 1) {
        index = (index + k - 1) % n;
        printf("%d\n", circle[index]);
        for (int i = index; i < n - 1; i++) {
            circle[i] = circle[i + 1];
        }
        n--;
    }
    printf("%d\n", circle[0]);
    free(circle);
    return 0;
}
